import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import * as raffleService from '../api/raffleService';

const PAYMENT_METHODS = [
  { key: 'acceptPayPal',       label: 'PayPal' },
  { key: 'acceptRevolut',      label: 'Revolut' },
  { key: 'acceptBankTransfer', label: 'Bank Transfer / SEPA' },
  { key: 'acceptViva',         label: 'Viva Wallet' },
  { key: 'acceptIris',         label: 'IRIS Pay' },
  { key: 'acceptDM',           label: 'Arrange via DM' },
];

export default function RaffleCreateForm({ onBack }) {
  const navigate = useNavigate();

  const [form, setForm] = useState({
    title: '',
    description: '',
    itemImageUrl: '',
    totalSpots: 50,
    pricePerSpot: 10,
    endsAt: '',
    acceptPayPal: false,
    acceptRevolut: false,
    acceptBankTransfer: false,
    acceptViva: false,
    acceptIris: false,
    acceptDM: true,
    paymentDetails: '',
  });

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  function set(field, value) {
    setForm(f => ({ ...f, [field]: value }));
  }

  async function handleSubmit(e) {
    e.preventDefault();
    setError('');

    const anyPayment = PAYMENT_METHODS.some(m => form[m.key]);
    if (!anyPayment) {
      setError('Please select at least one payment method.');
      return;
    }
    if (!form.endsAt) {
      setError('Please set an end date.');
      return;
    }
    if (new Date(form.endsAt) <= new Date()) {
      setError('End date must be in the future.');
      return;
    }

    try {
      setLoading(true);
      const created = await raffleService.createRaffle({
        ...form,
        totalSpots: Number(form.totalSpots),
        pricePerSpot: Number(form.pricePerSpot),
        endsAt: new Date(form.endsAt).toISOString(),
      });
      navigate(`/raffles/${created.id}`);
    } catch (err) {
      setError(err?.response?.data?.message || 'Failed to create raffle.');
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="max-w-2xl mx-auto p-6">
      <div className="flex items-center gap-3 mb-6">
        <button onClick={onBack || (() => navigate('/raffles'))} className="text-gray-400 hover:text-white transition">
          ← Back
        </button>
        <h1 className="text-2xl font-bold text-white">Create a Raffle</h1>
      </div>

      <form onSubmit={handleSubmit} className="space-y-5">

        {/* Title */}
        <div>
          <label className="block text-sm text-gray-400 mb-1">Item Title *</label>
          <input
            required
            maxLength={200}
            value={form.title}
            onChange={e => set('title', e.target.value)}
            className="w-full bg-surface-2 border border-white/10 rounded-lg px-3 py-2 text-white focus:outline-none focus:border-primary"
            placeholder="e.g. Meucci Original 97-3 Custom Cue"
          />
        </div>

        {/* Description */}
        <div>
          <label className="block text-sm text-gray-400 mb-1">Description</label>
          <textarea
            maxLength={2000}
            rows={3}
            value={form.description}
            onChange={e => set('description', e.target.value)}
            className="w-full bg-surface-2 border border-white/10 rounded-lg px-3 py-2 text-white focus:outline-none focus:border-primary resize-none"
            placeholder="Describe the item, condition, shipping details…"
          />
        </div>

        {/* Image URL */}
        <div>
          <label className="block text-sm text-gray-400 mb-1">Item Image URL (optional)</label>
          <input
            value={form.itemImageUrl}
            onChange={e => set('itemImageUrl', e.target.value)}
            className="w-full bg-surface-2 border border-white/10 rounded-lg px-3 py-2 text-white focus:outline-none focus:border-primary"
            placeholder="https://…"
          />
        </div>

        {/* Spots + Price */}
        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="block text-sm text-gray-400 mb-1">Total Spots *</label>
            <input
              type="number"
              required
              min={2}
              max={1000}
              value={form.totalSpots}
              onChange={e => set('totalSpots', e.target.value)}
              className="w-full bg-surface-2 border border-white/10 rounded-lg px-3 py-2 text-white focus:outline-none focus:border-primary"
            />
          </div>
          <div>
            <label className="block text-sm text-gray-400 mb-1">Price per Spot (€) *</label>
            <input
              type="number"
              required
              min={0.01}
              step={0.01}
              value={form.pricePerSpot}
              onChange={e => set('pricePerSpot', e.target.value)}
              className="w-full bg-surface-2 border border-white/10 rounded-lg px-3 py-2 text-white focus:outline-none focus:border-primary"
            />
          </div>
        </div>

        {/* Total pot display */}
        <p className="text-sm text-gray-400">
          Total pot: <span className="text-primary font-semibold">€{(form.totalSpots * form.pricePerSpot).toFixed(2)}</span>
        </p>

        {/* End date */}
        <div>
          <label className="block text-sm text-gray-400 mb-1">Raffle Ends At *</label>
          <input
            type="datetime-local"
            required
            value={form.endsAt}
            onChange={e => set('endsAt', e.target.value)}
            className="w-full bg-surface-2 border border-white/10 rounded-lg px-3 py-2 text-white focus:outline-none focus:border-primary"
          />
        </div>

        {/* Payment methods */}
        <div>
          <label className="block text-sm text-gray-400 mb-2">Accepted Payment Methods *</label>
          <div className="flex flex-wrap gap-3">
            {PAYMENT_METHODS.map(({ key, label }) => (
              <label key={key} className="flex items-center gap-2 cursor-pointer">
                <input
                  type="checkbox"
                  checked={form[key]}
                  onChange={e => set(key, e.target.checked)}
                  className="accent-primary"
                />
                <span className="text-sm text-gray-300">{label}</span>
              </label>
            ))}
          </div>
        </div>

        {/* Payment details */}
        <div>
          <label className="block text-sm text-gray-400 mb-1">Payment Details (shown to entrants)</label>
          <textarea
            maxLength={500}
            rows={2}
            value={form.paymentDetails}
            onChange={e => set('paymentDetails', e.target.value)}
            className="w-full bg-surface-2 border border-white/10 rounded-lg px-3 py-2 text-white focus:outline-none focus:border-primary resize-none"
            placeholder="e.g. PayPal: seller@email.com | Revolut: @myhandle | IBAN: GR…"
          />
        </div>

        {error && <p className="text-red-400 text-sm">{error}</p>}

        <button
          type="submit"
          disabled={loading}
          className="w-full py-3 rounded-lg bg-primary hover:bg-primary/80 text-white font-bold transition disabled:opacity-50"
        >
          {loading ? 'Creating…' : 'Create Raffle 🎰'}
        </button>
      </form>
    </div>
  );
}
