import React, { useEffect, useRef, useState } from 'react';

/**
 * SpinWheel modal.
 * Shows an animated spinning slots / ticker effect, then reveals the winner.
 *
 * Props:
 *   raffle         – RaffleResponseDto (must be status "drawn" with winnerId set)
 *   onClose        – callback to close the modal
 */
export default function SpinWheel({ raffle, onClose }) {
  const [phase, setPhase] = useState('spinning'); // spinning | revealing | done
  const [displayName, setDisplayName] = useState('???');
  const intervalRef = useRef(null);

  const paidEntries = (raffle.entries || []).filter(e => e.status === 'paid');
  const winner = raffle.winnerUsername || raffle.winnerId;

  useEffect(() => {
    if (paidEntries.length === 0) {
      setPhase('done');
      setDisplayName(winner || '???');
      return;
    }

    // Phase 1: rapid shuffle for 2.5 s
    let tick = 0;
    intervalRef.current = setInterval(() => {
      const rnd = paidEntries[Math.floor(Math.random() * paidEntries.length)];
      setDisplayName(rnd.username);
      tick++;
      // Slow down after 40 ticks
      if (tick > 40) {
        clearInterval(intervalRef.current);
        // Phase 2: slow reveal
        let slowTick = 0;
        const slow = setInterval(() => {
          const rnd2 = paidEntries[Math.floor(Math.random() * paidEntries.length)];
          setDisplayName(rnd2.username);
          slowTick++;
          if (slowTick > 8) {
            clearInterval(slow);
            setPhase('revealing');
            setTimeout(() => {
              setDisplayName(raffle.winnerUsername || `User #${raffle.winnerId}`);
              setPhase('done');
            }, 600);
          }
        }, 200);
      }
    }, 60);

    return () => clearInterval(intervalRef.current);
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  return (
    <div className="fixed inset-0 z-50 bg-black/90 flex items-center justify-center p-4">
      <div className="bg-surface-2 border border-white/10 rounded-2xl w-full max-w-sm text-center p-8 shadow-2xl">
        <div className="text-4xl mb-4">🎰</div>
        <h2 className="text-xl font-bold text-white mb-6">Drawing Winner…</h2>

        {/* Slot display */}
        <div
          className={`
            rounded-xl border-2 py-6 px-4 mb-6 transition-all duration-500
            ${phase === 'done'
              ? 'border-yellow-400 bg-yellow-400/10'
              : 'border-primary/60 bg-primary/5'}
          `}
        >
          <p
            className={`
              text-2xl font-mono font-bold transition-all duration-300
              ${phase === 'done' ? 'text-yellow-300 scale-110' : 'text-primary animate-pulse'}
            `}
          >
            {displayName}
          </p>
          {phase === 'done' && raffle.winnerSpotNumber && (
            <p className="text-sm text-gray-400 mt-1">Spot #{raffle.winnerSpotNumber}</p>
          )}
        </div>

        {phase === 'done' && (
          <>
            <p className="text-green-400 font-semibold mb-4">🏆 Congratulations!</p>
            <button
              onClick={onClose}
              className="w-full py-2 rounded-lg bg-primary hover:bg-primary/80 text-white font-semibold transition"
            >
              Close
            </button>
          </>
        )}

        {phase !== 'done' && (
          <p className="text-gray-500 text-sm animate-pulse">Spinning…</p>
        )}
      </div>
    </div>
  );
}
